import csv

# Analyze the additional text patterns: Station=, FailCode=, BST 异常, etc.
with open('/app/data/test_center_logs.csv', 'r') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# Check for special patterns
from collections import Counter
special = Counter()
for row in rows:
    t = row['raw_reason_text']
    if 'Station=' in t:
        special['Station='] += 1
    if 'FailCode=' in t:
        special['FailCode='] += 1
    if 'BST 异常' in t or 'BST异常' in t:
        special['BST 异常'] += 1
    if 'BURNIN 异常' in t:
        special['BURNIN 异常'] += 1
    if '异常' in t and '需确认原因' in t:
        special['异常需确认原因'] += 1
    if 'OS fail' in t:
        special['OS fail'] += 1
    if 'OS，' in t or 'OS (open)' in t or 'OS (short)' in t:
        special['OS pattern'] += 1

for s, c in special.most_common():
    print(f'  {s}: {c}')

# Look at OS pattern more closely (seems to be abbreviated from open/short)
