import json

with open('/app/output/solution.json', 'r') as f:
    data = json.load(f)

# Check span_text validity - must be substring of raw_reason_text
invalid_spans = 0
for rec in data['records']:
    for seg in rec['normalized']:
        if seg['span_text'] not in rec['raw_reason_text']:
            invalid_spans += 1
            if invalid_spans <= 5:
                print(f'INVALID SPAN in {rec[\"record_id\"]}:')
                print(f'  raw: {rec[\"raw_reason_text\"][:100]}')
                print(f'  span: {seg[\"span_text\"][:100]}')
                print()

print(f'Total invalid spans: {invalid_spans}')

# Check UNKNOWN confidence < non-UNKNOWN
unknown_confs = [s['confidence'] for r in data['records'] for s in r['normalized'] if s['pred_code'] == 'UNKNOWN']
non_unknown_confs = [s['confidence'] for r in data['records'] for s in r['normalized'] if s['pred_code'] != 'UNKNOWN']
print(f'UNKNOWN conf range: {min(unknown_confs):.3f} - {max(unknown_confs):.3f}')
print(f'Non-UNKNOWN conf range: {min(non_unknown_confs):.3f} - {max(non_unknown_confs):.3f}')
print(f'UNKNOWN max < Non-UNKNOWN min? {max(unknown_confs) < min(non_unknown_confs)}')

# Check pred_code and pred_label exist in codebook
import csv
valid_codes = {}
for product in ['P1_POWER', 'P2_CTRL', 'P3_RF']:
    with open(f'/app/data/codebook_{product}.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            valid_codes[row['code'].strip()] = row['standard_label'].strip()

invalid_codes = 0
for rec in data['records']:
    for seg in rec['normalized']:
        if seg['pred_code'] != 'UNKNOWN':
            if seg['pred_code'] not in valid_codes:
                invalid_codes += 1
                if invalid_codes <= 3:
                    print(f'INVALID CODE: {seg[\"pred_code\"]} in {rec[\"record_id\"]}')
            elif valid_codes[seg['pred_code']] != seg['pred_label']:
                invalid_codes += 1
                if invalid_codes <= 3:
                    print(f'LABEL MISMATCH: {seg[\"pred_code\"]} -> {seg[\"pred_label\"]} vs {valid_codes[seg[\"pred_code\"]]}')

print(f'Total invalid codes/labels: {invalid_codes}')
